<?php
namespace qqworld_collector\module\collect_filter; use QL\QueryList; use voku\helper\HtmlDomParser; class replace_html_tags extends filter { public function inlucdes() { if ( $this->options->qc_collection_project_core == 'querylist' ) { if (!class_exists('QL\QueryList')) require WP_CONTENT_DIR . DIRECTORY_SEPARATOR . 'libs' . DIRECTORY_SEPARATOR . 'querylist' . DIRECTORY_SEPARATOR . 'autoload.php'; if (!$this->ql) $this->ql = QueryList::getInstance(); } else { if (!function_exists('voku\helper\HtmlDomParser')) { require WP_CONTENT_DIR . DIRECTORY_SEPARATOR . 'libs' . DIRECTORY_SEPARATOR . 'voku' . DIRECTORY_SEPARATOR . 'simple_html_dom' . DIRECTORY_SEPARATOR . 'autoload.php'; } } } public function filter($item, $args, $source_link, $html, $type, $item_args, $download_args, $mode) { $value = isset($args['value']) ? $args['value'] : ''; if ($value) { $this->inlucdes(); $value = explode("\r\n", $value); foreach ($value as $val) { $val = explode('=>', $val); if (count($val) == 2) { $selector = trim($val[0]); $selector = html_entity_decode($selector); $this->tag = trim($val[1]); if ( $this->options->qc_collection_project_core == 'querylist' ) { $parser = $this->ql->html('<div class="qqworld-querylist-container">'.$item.'</div>'); $parser->find($selector)->map(function($element){ $element->replaceWith("<{$this->tag}>".$element->html()."</{$this->tag}>"); }); $item = $parser->find('.qqworld-querylist-container')->html(); } else { if ($this->tag == 'p') { $patterns = array("</{$selector}>"); $replacements = array("</{$this->tag}>"); $preg = preg_match_all('/<'.$selector.'([^>]*?)>/i', $item, $matches); if ($preg) { foreach ($matches[1] as $index => $match) { if (in_array($matches[0][$index], $patterns)) continue; if (empty($match) || preg_match('/^\s/', $match)) { $patterns[] = $matches[0][$index]; $replacements[] = "<{$this->tag}{$match}>"; } } } $item = str_replace($patterns, $replacements, $item); } else { $parser = HtmlDomParser::str_get_html($item); if (is_object($parser)) { $elementsOrFalse = $parser->findMultiOrFalse($selector); if ($elementsOrFalse !== false) { foreach ($elementsOrFalse as $element) { $element->outerhtml = "<{$this->tag}>".$element->innerhtml."</{$this->tag}>"; } } $item = $parser->save(); } } } } } } return $item; } } ?>